import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict with side, price, qty, arrival, active
    arrival_counter = 0

    def add_resting(order_id, side, price, qty, arrival):
        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'arrival': arrival, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, order_id))
        else:
            heapq.heappush(sell_heap, (price, arrival, order_id))

    def cancel_order(order_id):
        if order_id in book and book[order_id]['active']:
            book[order_id]['active'] = False
            # qty stays but active False, will be lazily removed from heap

    def process_incoming(side, price, qty, order_id, order_type, arrival):
        remaining = qty
        if side == 'buy':
            # match against sell_heap
            while remaining > 0 and sell_heap:
                top_price, top_arrival, top_id = sell_heap[0]
                # check validity
                if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if order_type == 'market' or price >= top_price:
                    # match
                    resting = book[top_id]
                    trade_qty = min(remaining, resting['qty'])
                    trades.append([order_id, top_id, resting['price'], trade_qty])
                    remaining -= trade_qty
                    resting['qty'] -= trade_qty
                    if resting['qty'] == 0:
                        resting['active'] = False
                        heapq.heappop(sell_heap)
                    # if remaining==0 loop will end
                else:
                    break
        else:
            # sell side, match against buy_heap
            while remaining > 0 and buy_heap:
                neg_price, top_arrival, top_id = buy_heap[0]
                top_price = -neg_price
                if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if order_type == 'market' or price <= top_price:
                    resting = book[top_id]
                    trade_qty = min(remaining, resting['qty'])
                    trades.append([top_id, order_id, resting['price'], trade_qty])
                    remaining -= trade_qty
                    resting['qty'] -= trade_qty
                    if resting['qty'] == 0:
                        resting['active'] = False
                        heapq.heappop(buy_heap)
                else:
                    break
        return remaining

    for order in orders:
        op = order[0]
        if op == 'cancel':
            _, order_id = order
            cancel_order(order_id)
            continue

        arrival_counter += 1
        arrival = arrival_counter

        if op == 'limit':
            _, order_id, side, price, qty = order
            remaining = process_incoming(side, price, qty, order_id, 'limit', arrival)
            if remaining > 0:
                add_resting(order_id, side, price, remaining, arrival)
            else:
                book[order_id] = {'side': side, 'price': price, 'qty': 0, 'arrival': arrival, 'active': False}

        elif op == 'ioc':
            _, order_id, side, price, qty = order
            remaining = process_incoming(side, price, qty, order_id, 'ioc', arrival)
            book[order_id] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': False}

        elif op == 'market':
            _, order_id, side, qty = order
            remaining = process_incoming(side, None, qty, order_id, 'market', arrival)
            book[order_id] = {'side': side, 'price': None, 'qty': remaining, 'arrival': arrival, 'active': False}

    return trades

